SELECT 'gongkao', '平均数概述', 'kp-xc-data-average-overview', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"平均数概述"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"平均数约 3 题。核心公式：平均数 = 总量/份数。难点在于平均数增长率和平均数增长量的计算。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、包含的子类"}]},{"type":"columns","content":[{"type":"column","content":[{"type":"paragraph","content":[{"type":"text","text":"子类"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"现期平均数：当前时期的平均值"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期平均数：过去时期的平均值"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"两期平均数：两个时期平均值的差"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"平均数增长率：平均值增长了百分之几"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"平均数增长量：平均值增长了多少"}]}]}]}]},{"type":"column","content":[{"type":"paragraph","content":[{"type":"text","text":"核心公式"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"总量/份数"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"含 r 修正"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"现期-基期"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"(总量r-份数r)/(1+份数r)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"现期-基期"}]}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心公式"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"现期平均数 = 总量(A) / 份数(B)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期平均数 = (A/B) × (1+b)/(1+a)，其中 a=总量增长率，b=份数增长率"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"平均数增长率 = (a-b)/(1+b)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"平均数增长量 = 现期平均数 × (a-b)/(1+a)"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"平均数增长率公式不要记错 — (a-b)/(1+b)，不是 (a-b)/(1+a)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"平均数升降判断：a > b 则平均数上升，a < b 则下降"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"注意总量和份数的区分 — 分子是总量，分母是份数"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"平均数公式与比重公式类似，建议对比记忆。重点练习平均数增长率。"}]}]}]}]}$$ AS jsonb), NULL, '平均数概述：现期平均数、基期平均数、平均数增长率、平均数增长量。', category_node.id, CAST('["资料分析", "平均数"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_average", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
